import type {TopicDeepening} from './topicDeepening';
import type {C1Section} from './c1Curriculum';
import {c1FoundationExpansion} from './c1FoundationExpansion';
import {c1SurvivalExpansion} from './c1SurvivalExpansion';
type Local={fr:string;de:string;es:string};
const q=(prompt:string,choices:[string,string,string],correctIndex:number,explanation:string,evidence:Local)=>({prompt,choices,correctIndex,explanation,evidence});
const n=(explanation:string,first:string,second:string,difference:string,phrases:[string,string][])=>({explanation,first,second,difference,phrases:phrases.map(([text,meaning])=>({text,meaning}))});
/** Original fictional C1 material. Topics without an exact match remain explicitly unavailable. */
const initial:readonly TopicDeepening[]=[
{id:'c1-advanced-time-review',level:'c1',section:'foundation',number:3,title:'زمان‌های پیشرفته در گزارش یک پروژه',passage:{
fr:'Au printemps dernier, l’équipe d’un musée préparait une exposition sur la mémoire du quartier. Avant de fixer le programme, elle avait interrogé des habitants et recueilli leur accord écrit pour utiliser certains témoignages. En juin, une participante a demandé le retrait d’un extrait ; l’équipe l’a immédiatement supprimé et lui a envoyé une confirmation. Elle révisait encore les autres textes lorsque la date d’ouverture a été reportée. D’ici à la prochaine réunion, les responsables auront vérifié les autorisations restantes, mais ils ne publieront rien tant que les personnes concernées n’auront pas confirmé leur choix. Dans le bilan, la responsable distingue les actions déjà accomplies de celles qui ne seront achevées qu’avant une échéance future.',
de:'Im vergangenen Frühjahr bereitete ein Museumsteam eine Ausstellung zur Geschichte des Viertels vor. Bevor es das Programm festlegte, hatte es Bewohner befragt und deren schriftliche Einwilligung für bestimmte Beiträge eingeholt. Im Juni bat eine Teilnehmerin darum, einen Ausschnitt zurückzuziehen; das Team entfernte ihn und bestätigte ihr dies. Hätte es den Wunsch ignoriert, hätte es das Vertrauen der Beteiligten gefährdet. Bis zur nächsten Sitzung wird das Team die übrigen Einwilligungen geprüft haben; veröffentlichen wird es jedoch erst, wenn die Betroffenen ihre Wahl bestätigt haben. Im Bericht unterscheidet die Leiterin abgeschlossene Schritte, vorausgehende Handlungen und einen Abschluss vor einem zukünftigen Zeitpunkt.',
es:'La primavera pasada, un equipo de un museo preparaba una exposición sobre la memoria del barrio. Antes de fijar el programa, había entrevistado a vecinos y obtenido su consentimiento escrito para utilizar algunos testimonios. En junio, una participante pidió retirar un fragmento; el equipo lo eliminó y le envió una confirmación. Si hubiera ignorado la petición, habría puesto en riesgo la confianza de los participantes. Para la próxima reunión, los responsables habrán comprobado las autorizaciones restantes, pero no publicarán nada hasta que las personas afectadas confirmen su elección. En el informe, la responsable distingue las acciones ya realizadas de las que se completarán antes de un plazo futuro.'},
questions:[q('پیش از نهایی کردن برنامه چه کاری انجام شده بود؟',['مصاحبه و دریافت رضایت کتبی','انتشار بدون رضایت','حذف همهٔ شهادت‌ها'],0,'مصاحبه و دریافت رضایت پیش از تعیین برنامه انجام شده بود.',{fr:'avait interrogé des habitants et recueilli leur accord écrit',de:'hatte es Bewohner befragt und deren schriftliche Einwilligung',es:'había entrevistado a vecinos y obtenido su consentimiento escrito'}),q('پس از درخواست شرکت‌کننده چه کردند؟',['درخواست را رد کردند','قطعه را حذف و تأیید ارسال کردند','فقط تاریخ نمایشگاه را تغییر دادند'],1,'قطعه حذف و تأیید ارسال شد.',{fr:'l’équipe l’a immédiatement supprimé et lui a envoyé une confirmation',de:'das Team entfernte ihn und bestätigte ihr dies',es:'el equipo lo eliminó y le envió una confirmación'}),q('انتشار به چه چیزی وابسته است؟',['فقط اتمام طراحی پوستر','پایان جلسه بدون بررسی','تأیید انتخاب افراد مربوط'],2,'پیش از انتشار باید افراد مربوط انتخاب خود را تأیید کنند.',{fr:'tant que les personnes concernées n’auront pas confirmé leur choix',de:'erst, wenn die Betroffenen ihre Wahl bestätigt haben',es:'hasta que las personas afectadas confirmen su elección'})],
notes:{fr:n('در این روایت imparfait زمینهٔ جاری، passé composé رویداد پایان‌یافته و plus-que-parfait اقدام پیش از نقطه‌ای در گذشته را نشان می‌دهد. Futur antérieur در «auront vérifié» تکمیل پیش از زمانی آینده را بیان می‌کند؛ در جملهٔ زمانی پس از «tant que» نیز تأیید پیش از انتشار قرار می‌گیرد.','L’équipe préparait l’exposition quand une participante a retiré un extrait.','D’ici à la réunion, les responsables auront vérifié les autorisations.','اولی زمینه و رخداد گذشته را تقابل می‌دهد؛ دومی پایان کار پیش از موعد آینده را نشان می‌دهد.',[['recueillir un accord écrit','گرفتن رضایت کتبی'],['retirer un extrait','پس گرفتن بخشی از متن'],['vérifier les autorisations','بررسی مجوزها']]),de:n('Plusquamperfekt عمل پیش از نقطهٔ گذشته را نشان می‌دهد. Futur II در این بافت پایان کار تا موعد آینده را بیان می‌کند؛ شکل «hätte ... gefährdet» در شرط خلاف واقع نتیجه‌ای تحقق‌نیافته در گذشته است.','Vor der Planung hatte das Team Einwilligungen eingeholt.','Bis zur Sitzung wird es die übrigen Einwilligungen geprüft haben.','اولی نسبت به گذشته پیشین است؛ دومی از تکمیل تا یک موعد آینده سخن می‌گوید.',[['eine Einwilligung einholen','گرفتن رضایت'],['einen Ausschnitt zurückziehen','پس گرفتن بخشی از متن'],['Zugriff und Freigabe prüfen','بررسی دسترسی و مجوز']]),es:n('Pluscuamperfecto اقدام پیش از رویداد گذشته را بیان می‌کند. Futuro perfecto می‌تواند تکمیل تا موعد آینده را نشان دهد و condicional compuesto در این متن نتیجهٔ خلاف واقعِ گذشته است.','Antes de fijar el programa, el equipo había pedido el consentimiento.','Para la reunión, habrá comprobado las autorizaciones.','اولی نسبت به گذشته پیشین است؛ دومی از تکمیل تا یک موعد آینده سخن می‌گوید.',[['obtener el consentimiento','گرفتن رضایت'],['retirar un fragmento','پس گرفتن بخشی از متن'],['comprobar las autorizaciones','بررسی مجوزها']])},
speaking:'برای اعضای تیم، رویدادها را با تمایز زمینه، اقدام قبلی، درخواست حذف و اقدام پیش‌بینی‌شده تا جلسه بازگو کنید؛ قطعیت آینده را بیش از متن فرض نکنید.',writing:'گزارشی دربارهٔ مدیریت رضایت بنویسید که ترتیب رویدادها و شرط انتشار را روشن کند.',steps:['زمینهٔ پروژه و اقدام پیش از برنامه را معرفی کنید.','درخواست حذف و پاسخ را گزارش کنید.','اقدام مورد انتظار تا جلسه را با ساختار مناسب زمان بیان کنید.','شرط انتشار و محدودیت نتیجه را روشن کنید.'],model:{fr:'L’équipe préparait une exposition et avait déjà recueilli des accords écrits avant de fixer le programme. En juin, une participante a retiré un extrait ; l’équipe l’a supprimé et lui a confirmé cette suppression. D’ici à la réunion, les responsables auront vérifié les autorisations restantes. Toutefois, aucun témoignage ne sera publié avant que les personnes concernées aient confirmé leur choix. Ce calendrier distingue une vérification prévue d’une autorisation effective.',de:'Das Team bereitete eine Ausstellung vor und hatte vor der Programmplanung schriftliche Einwilligungen eingeholt. Im Juni zog eine Teilnehmerin einen Ausschnitt zurück; das Team entfernte ihn und bestätigte dies. Hätte es den Wunsch ignoriert, hätte es das Vertrauen gefährdet. Bis zur Sitzung wird es die übrigen Einwilligungen geprüft haben. Veröffentlicht wird jedoch erst nach der Bestätigung der Betroffenen; ein Prüfplan ersetzt keine Freigabe.',es:'El equipo preparaba una exposición y había obtenido consentimientos escritos antes de fijar el programa. En junio, una participante retiró un fragmento; el equipo lo eliminó y confirmó la eliminación. Si hubiera ignorado la petición, habría puesto en riesgo la confianza. Para la reunión habrá comprobado las autorizaciones restantes. No obstante, no publicará los testimonios hasta que las personas afectadas confirmen su elección; una comprobación prevista no sustituye al consentimiento.'}},
{id:'c1-counterfactual-policy',level:'c1',section:'foundation',number:5,title:'فرض خلاف واقع و پیامد در زمان دیگر',passage:{
fr:'Une commune a lancé l’an dernier un service de vélos partagés sans consulter les habitants des quartiers périphériques. Les premières stations ont été installées près du centre, et plusieurs quartiers éloignés restent aujourd’hui mal desservis. Lors d’une réunion, Farid affirme que, si la commune avait consulté ces habitants avant le lancement, elle aurait peut-être choisi d’autres emplacements ; leur accès serait probablement meilleur aujourd’hui. Il précise toutefois qu’une consultation n’aurait pas forcément résolu les contraintes de budget et qu’il est impossible de connaître avec certitude le résultat d’un scénario qui ne s’est pas produit. La commune prévoit maintenant d’étudier les trajets et d’inviter les habitants à comparer plusieurs options avant toute extension.',
de:'Eine Gemeinde führte im vergangenen Jahr ein Fahrradverleihsystem ein, ohne die Bewohner der Randgebiete zu befragen. Die ersten Stationen wurden nahe dem Zentrum eingerichtet, und mehrere entfernte Viertel sind bis heute schlecht angebunden. In einer Sitzung erklärt Farid, dass die Gemeinde möglicherweise andere Standorte gewählt hätte, wenn sie diese Bewohner vor dem Start befragt hätte; ihr Zugang wäre heute wahrscheinlich besser. Er betont jedoch, dass eine Befragung die Budgetgrenzen nicht unbedingt beseitigt hätte und das Ergebnis eines nicht eingetretenen Szenarios nicht sicher bekannt sein kann. Nun will die Gemeinde Wege untersuchen und die Bewohner vor jeder Erweiterung verschiedene Optionen vergleichen lassen.',
es:'El año pasado, un municipio puso en marcha un servicio de bicicletas compartidas sin consultar a los habitantes de los barrios periféricos. Las primeras estaciones se instalaron cerca del centro y varios barrios alejados siguen estando mal comunicados. En una reunión, Farid afirma que, si el municipio hubiera consultado a esos habitantes antes del lanzamiento, quizá habría elegido otros lugares y su acceso sería probablemente mejor hoy. No obstante, precisa que una consulta no habría resuelto necesariamente las limitaciones presupuestarias y que no se puede conocer con certeza el resultado de un escenario que no ocurrió. Ahora el municipio prevé estudiar los desplazamientos e invitar a los habitantes a comparar varias opciones antes de cualquier ampliación.'},
questions:[q('چه چیزی در برنامهٔ اولیه اتفاق نیفتاد؟',['مشورت با ساکنان حاشیه پیش از شروع','نصب ایستگاه‌های نزدیک مرکز','راه‌اندازی خدمت در سال گذشته'],0,'ساکنان حاشیه پیش از شروع طرف مشورت قرار نگرفتند.',{fr:'sans consulter les habitants des quartiers périphériques',de:'ohne die Bewohner der Randgebiete zu befragen',es:'sin consultar a los habitantes de los barrios periféricos'}),q('پیامد فرضی امروز از نظر فرید چیست؟',['دسترسی قطعاً برابر و کامل می‌شد','دسترسی احتمالاً بهتر می‌بود','بودجه الزاماً دو برابر می‌شد'],1,'او بهبود احتمالی دسترسی امروز را مطرح می‌کند.',{fr:'leur accès serait probablement meilleur aujourd’hui',de:'ihr Zugang wäre heute wahrscheinlich besser',es:'su acceso sería probablemente mejor hoy'}),q('چه محدودیتی دربارهٔ این فرض مطرح می‌شود؟',['سناریو واقعاً رخ داده است','مشورت لزوماً بودجه را افزایش می‌داد','نتیجهٔ سناریوی رخ‌نداده قطعی دانسته نمی‌شود'],2,'نتیجهٔ یک سناریوی رخ‌نداده را نمی‌توان با قطعیت دانست.',{fr:'impossible de connaître avec certitude le résultat d’un scénario qui ne s’est pas produit',de:'das Ergebnis eines nicht eingetretenen Szenarios nicht sicher bekannt sein kann',es:'no se puede conocer con certeza el resultado de un escenario que no ocurrió'})],
notes:{fr:n('«Si + plus-que-parfait» شرط تحقق‌نیافتهٔ گذشته را می‌سازد. نتیجه می‌تواند conditionnel passé برای پیامد گذشته یا conditionnel présent برای وضعیت کنونی باشد؛ «peut-être» قطعیت نتیجه را محدود می‌کند.','Si la commune avait consulté les habitants, elle aurait peut-être choisi d’autres sites.','Si elle les avait consultés, l’accès serait probablement meilleur aujourd’hui.','شرط هر دو در گذشته است؛ نتیجهٔ اول گذشته و نتیجهٔ دوم اکنون است.',[['un quartier périphérique','محلهٔ حاشیه‌ای'],['une contrainte budgétaire','محدودیت بودجه'],['un scénario non réalisé','سناریوی تحقق‌نیافته']]),de:n('در شرط خلاف واقع گذشته از «wenn ... hätte» و در نتیجهٔ گذشته از Konjunktiv II Vergangenheit استفاده می‌شود؛ نتیجهٔ مربوط به اکنون می‌تواند «wäre heute» باشد.','Wenn die Gemeinde die Bewohner befragt hätte, hätte sie vielleicht andere Standorte gewählt.','Wenn sie sie befragt hätte, wäre der Zugang heute vermutlich besser.','شرط هر دو در گذشته است؛ نتیجهٔ اول گذشته و نتیجهٔ دوم اکنون است.',[['ein Randgebiet','محلهٔ حاشیه‌ای'],['eine Budgetgrenze','محدودیت بودجه'],['ein nicht eingetretenes Szenario','سناریوی تحقق‌نیافته']]),es:n('«Si + pluscuamperfecto de subjuntivo» شرط تحقق‌نیافته در گذشته را نشان می‌دهد؛ نتیجهٔ گذشته می‌تواند condicional compuesto و پیامد کنونی condicional simple باشد.','Si el municipio hubiera consultado a los vecinos, quizá habría elegido otros lugares.','Si los hubiera consultado, el acceso sería probablemente mejor hoy.','شرط هر دو در گذشته است؛ نتیجهٔ اول گذشته و نتیجهٔ دوم اکنون است.',[['un barrio periférico','محلهٔ حاشیه‌ای'],['una limitación presupuestaria','محدودیت بودجه'],['un escenario que no ocurrió','سناریوی تحقق‌نیافته']])},
speaking:'فرض فرید را بازسازی کنید، نتیجهٔ گذشته و اثر فرضی کنونی را تفکیک و محدودیت دانش دربارهٔ سناریوی رخ‌نداده را توضیح دهید.',writing:'یادداشت سیاستی بنویسید: تصمیم گذشته، دو نتیجهٔ فرضی در زمان متفاوت، محدودیت‌ها و اقدامی برای آینده.',steps:['واقعیت تصمیم و وضعیت کنونی را از فرض جدا کنید.','یک پیامد فرضی گذشته و یک پیامد فرضی کنونی بنویسید.','قطعیت و بودجه را با احتیاط ارزیابی کنید.','روش بررسی مشارکتی پیش از توسعه را پیشنهاد دهید.'],model:{fr:'La commune a installé les premières stations sans consulter les quartiers périphériques, dont l’accès reste limité. Si elle avait consulté les habitants, elle aurait peut-être choisi d’autres sites et l’accès serait probablement meilleur aujourd’hui. Nous ne pouvons toutefois pas savoir si cette consultation aurait suffi à surmonter les contraintes budgétaires. Avant toute extension, il serait utile d’étudier les trajets et de comparer les options avec les habitants.',de:'Die Gemeinde richtete die ersten Stationen ohne Befragung der Randgebiete ein, deren Zugang weiterhin begrenzt ist. Hätte sie die Bewohner befragt, hätte sie möglicherweise andere Standorte gewählt und der Zugang wäre heute vermutlich besser. Wir wissen jedoch nicht, ob eine Befragung die Budgetgrenzen überwunden hätte. Vor einer Erweiterung sollten Wege untersucht und Optionen gemeinsam mit den Bewohnern verglichen werden.',es:'El municipio instaló las primeras estaciones sin consultar a los barrios periféricos, cuyo acceso sigue siendo limitado. Si hubiera consultado a sus habitantes, quizá habría elegido otros lugares y el acceso sería probablemente mejor hoy. Sin embargo, no sabemos si la consulta habría superado las limitaciones presupuestarias. Antes de ampliar el servicio convendría estudiar los desplazamientos y comparar las opciones con los vecinos.'}},
{id:'c1-sensitive-negotiation',level:'c1',section:'survival',number:4,title:'مذاکرهٔ حساس دربارهٔ زمان و محرمانگی',passage:{
fr:'Une association et une société de recherche négocient la publication d’un rapport sur l’accès aux services publics. La société souhaite publier dans trois semaines, tandis que l’association demande davantage de temps pour vérifier que les témoignages ne permettent pas d’identifier les personnes. Le responsable de la société craint qu’un report compromette un financement, mais il accepte que la confidentialité ne soit pas négociable. Les deux parties envisagent de publier d’abord une note méthodologique sans témoignages et de soumettre le rapport complet à une vérification indépendante. Aucun calendrier définitif n’est adopté : l’association consultera les participants et la société vérifiera les conditions du financement. Elles conviennent de se retrouver lundi et de consigner par écrit les points encore ouverts.',
de:'Ein Verein und ein Forschungsunternehmen verhandeln über die Veröffentlichung eines Berichts zum Zugang zu öffentlichen Dienstleistungen. Das Unternehmen möchte in drei Wochen veröffentlichen, während der Verein mehr Zeit verlangt, um zu prüfen, ob Aussagen Rückschlüsse auf einzelne Personen erlauben. Der Verantwortliche des Unternehmens befürchtet, dass eine Verschiebung eine Finanzierung gefährden könnte, akzeptiert aber, dass Vertraulichkeit nicht verhandelbar ist. Beide Seiten erwägen, zunächst eine methodische Notiz ohne Aussagen zu veröffentlichen und den vollständigen Bericht unabhängig prüfen zu lassen. Ein endgültiger Zeitplan wird nicht beschlossen: Der Verein befragt die Beteiligten und das Unternehmen prüft die Finanzierungsbedingungen. Sie vereinbaren ein Treffen am Montag und halten die offenen Punkte schriftlich fest.',
es:'Una asociación y una empresa de investigación negocian la publicación de un informe sobre el acceso a los servicios públicos. La empresa desea publicarlo en tres semanas, mientras que la asociación pide más tiempo para comprobar que los testimonios no permitan identificar a las personas. El responsable de la empresa teme que un aplazamiento ponga en riesgo una financiación, pero acepta que la confidencialidad no es negociable. Ambas partes consideran publicar primero una nota metodológica sin testimonios y someter el informe completo a una revisión independiente. No se adopta un calendario definitivo: la asociación consultará a los participantes y la empresa comprobará las condiciones de la financiación. Acuerdan reunirse el lunes y dejar constancia por escrito de los puntos pendientes.'},
questions:[q('چرا انجمن زمان بیشتری می‌خواهد؟',['برای بررسی خطر شناسایی افراد در شهادت‌ها','برای حذف همهٔ اطلاعات روش‌شناسی','برای امضای قرارداد فروش داده'],0,'انجمن می‌خواهد خطر شناسایی افراد را بررسی کند.',{fr:'vérifier que les témoignages ne permettent pas d’identifier les personnes',de:'zu prüfen, ob Aussagen Rückschlüsse auf einzelne Personen erlauben',es:'comprobar que los testimonios no permitan identificar a las personas'}),q('گزینهٔ موقت مورد بررسی چیست؟',['انتشار فوری گزارش کامل بدون کنترل','انتشار یادداشت روش بدون شهادت و بررسی مستقل گزارش کامل','لغو بدون بازبینی هر نوع انتشار'],1,'دو طرف انتشار یادداشت روش و بازبینی مستقل گزارش کامل را بررسی می‌کنند.',{fr:'une note méthodologique sans témoignages et de soumettre le rapport complet à une vérification indépendante',de:'eine methodische Notiz ohne Aussagen zu veröffentlichen und den vollständigen Bericht unabhängig prüfen zu lassen',es:'una nota metodológica sin testimonios y someter el informe completo a una revisión independiente'}),q('وضعیت زمان‌بندی نهایی چیست؟',['هر دو انتشار کامل در سه هفته را قطعی کرده‌اند','سرمایه‌گذار تاریخ جدید را تأیید کرده است','هنوز برنامهٔ نهایی تصویب نشده است'],2,'هیچ زمان‌بندی نهایی اتخاذ نشده است.',{fr:'Aucun calendrier définitif n’est adopté',de:'Ein endgültiger Zeitplan wird nicht beschlossen',es:'No se adopta un calendario definitivo'})],
notes:{fr:n('در مذاکره، منافع طرفین را از مواضع و خطوط قرمز جدا کنید. «Sous réserve de» شرطی را مشخص می‌کند و به معنای توافق قطعی نیست.','Nous comprenons la contrainte de financement.','Une publication partielle serait envisageable sous réserve de vérifications.','اولی به رسمیت شناختن دغدغه و دومی امکان مشروط است.',[['une note méthodologique','یادداشت روش‌شناسی'],['sous réserve de vérification','مشروط به بررسی'],['consigner les points ouverts','ثبت موارد باز']]),de:n('در مذاکرهٔ حساس، نیاز طرف مقابل را تأیید کنید و محدودهٔ غیرقابل مذاکره و پیشنهاد مشروط را از توافق قطعی جدا کنید.','Wir verstehen die finanzielle Einschränkung.','Eine Teilveröffentlichung wäre vorbehaltlich der Prüfung denkbar.','اولی به رسمیت شناختن دغدغه و دومی امکان مشروط است.',[['eine methodische Notiz','یادداشت روش‌شناسی'],['vorbehaltlich der Prüfung','مشروط به بررسی'],['offene Punkte festhalten','ثبت موارد باز']]),es:n('در مذاکرهٔ حساس، دغدغهٔ طرف مقابل، خط قرمز و پیشنهاد مشروط را جدا کنید؛ «a reserva de» به‌تنهایی نشانهٔ توافق نهایی نیست.','Entendemos la limitación de la financiación.','Una publicación parcial sería posible a reserva de las comprobaciones.','اولی به رسمیت شناختن دغدغه و دومی امکان مشروط است.',[['una nota metodológica','یادداشت روش‌شناسی'],['a reserva de comprobación','مشروط به بررسی'],['dejar constancia de puntos pendientes','ثبت موارد باز']])},
speaking:'در نقش نمایندهٔ انجمن، نگرانی مالی طرف مقابل را بازگو کنید، خط قرمز محرمانگی را روشن کنید و راه‌حل مشروط و گام بعدی را مذاکره کنید.',writing:'صورت‌جلسه‌ای حرفه‌ای بنویسید که منافع، خط قرمز، گزینهٔ موقت، مسئول بررسی و زمان پیگیری را از توافق نهایی تفکیک کند.',steps:['مسئله و نگرانی هر طرف را توضیح دهید.','محرمانگی را به عنوان خط قرمز مشخص کنید.','گزینهٔ موقت را مشروط و بدون ادعای تصویب بیان کنید.','مسئولیت‌ها، موارد باز و موعد جلسهٔ بعدی را ثبت کنید.'],model:{fr:'La société souhaite publier dans trois semaines en raison d’une contrainte de financement ; l’association demande du temps pour vérifier le risque d’identification. Les parties reconnaissent que la confidentialité est indispensable. Elles étudieront une note méthodologique sans témoignages et une vérification indépendante du rapport complet. Aucun calendrier n’est encore adopté : l’association consultera les participants et la société examinera les conditions du financement. Les points ouverts seront revus lundi.',de:'Das Unternehmen möchte wegen einer Finanzierungsbedingung in drei Wochen veröffentlichen; der Verein benötigt Zeit, um das Identifizierungsrisiko zu prüfen. Beide Seiten erkennen die Vertraulichkeit als unverzichtbar an. Sie prüfen eine methodische Notiz ohne Aussagen und eine unabhängige Prüfung des vollständigen Berichts. Ein Zeitplan steht noch nicht fest: Der Verein befragt die Beteiligten und das Unternehmen prüft die Finanzierungsbedingungen. Die offenen Punkte werden am Montag besprochen.',es:'La empresa quiere publicar en tres semanas por una condición de financiación; la asociación necesita tiempo para comprobar el riesgo de identificación. Ambas partes reconocen que la confidencialidad es indispensable. Estudiarán una nota metodológica sin testimonios y una revisión independiente del informe completo. Todavía no hay un calendario definitivo: la asociación consultará a los participantes y la empresa revisará las condiciones de financiación. Los puntos pendientes se tratarán el lunes.'}},
{id:'c1-media-presupposition',level:'c1',section:'survival',number:14,title:'تشخیص سوگیری و پیش‌فرض در تیتر',passage:{
fr:'Un titre fictif annonce : « Enfin, les habitants acceptent le nouveau plan de circulation ». Le mot « enfin » suggère qu’une opposition collective aurait retardé une solution attendue, mais le texte qui suit rapporte seulement qu’un comité de douze personnes a recommandé un essai. Deux membres se sont abstenus et aucune enquête auprès de l’ensemble des habitants n’est mentionnée. Le plan prévoit aussi une consultation avant toute décision permanente. Une lectrice distingue donc la décision du comité de l’opinion de toute la population. Elle propose un titre plus précis : « Un comité recommande un essai du plan de circulation ». Elle souligne que même cette reformulation ne dit rien des raisons des abstentions, qui ne sont pas précisées.',
de:'Eine fiktive Überschrift lautet: „Endlich akzeptieren die Bewohner den neuen Verkehrsplan“. Das Wort „endlich“ legt nahe, dass ein kollektiver Widerstand eine erwartete Lösung verzögert habe; der anschließende Text berichtet jedoch nur, dass ein zwölfköpfiger Ausschuss einen Test empfohlen hat. Zwei Mitglieder enthielten sich und eine Befragung aller Bewohner wird nicht erwähnt. Der Plan sieht außerdem vor einer dauerhaften Entscheidung eine Konsultation vor. Eine Leserin unterscheidet daher die Empfehlung des Ausschusses von der Meinung der gesamten Bevölkerung. Sie schlägt eine präzisere Überschrift vor: „Ausschuss empfiehlt Test des Verkehrsplans“. Sie betont, dass auch diese Formulierung nichts über die Gründe der Enthaltungen aussagt, die nicht genannt werden.',
es:'Un titular ficticio anuncia: «Por fin, los vecinos aceptan el nuevo plan de tráfico». La expresión «por fin» sugiere que una oposición colectiva habría retrasado una solución esperada, pero el texto posterior solo informa de que un comité de doce personas recomendó una prueba. Dos miembros se abstuvieron y no se menciona ninguna encuesta a todos los vecinos. El plan también prevé una consulta antes de cualquier decisión permanente. Por eso una lectora distingue la recomendación del comité de la opinión de toda la población. Propone un titular más preciso: «Un comité recomienda probar el plan de tráfico». Señala que incluso esta formulación no explica los motivos de las abstenciones, que no se especifican.'},
questions:[q('متن پس از تیتر واقعاً از چه چیزی خبر می‌دهد؟',['توصیهٔ یک کمیتهٔ دوازده‌نفره برای آزمایش','پذیرش همهٔ ساکنان در همه‌پرسی','اجرای دائمی بدون مشورت'],0,'متن توصیهٔ کمیته‌ای دوازده‌نفره برای آزمایش را گزارش می‌کند.',{fr:'un comité de douze personnes a recommandé un essai',de:'ein zwölfköpfiger Ausschuss einen Test empfohlen hat',es:'un comité de doce personas recomendó una prueba'}),q('چه شواهدی دربارهٔ نظر همهٔ ساکنان ذکر نشده است؟',['تعداد اعضای کمیته','نظرسنجی از همهٔ ساکنان','وجود پیشنهاد آزمایش'],1,'نظرسنجی از همهٔ ساکنان ذکر نشده است.',{fr:'aucune enquête auprès de l’ensemble des habitants n’est mentionnée',de:'eine Befragung aller Bewohner wird nicht erwähnt',es:'no se menciona ninguna encuesta a todos los vecinos'}),q('علت ممتنع بودن دو عضو چیست؟',['مخالفت قطعی با تمام طرح','حمایت قطعی از اجرا','در متن مشخص نشده است'],2,'دلیل ممتنع بودن در متن بیان نشده است.',{fr:'des raisons des abstentions, qui ne sont pas précisées',de:'die Gründe der Enthaltungen aussagt, die nicht genannt werden',es:'los motivos de las abstenciones, que no se especifican'})],
notes:{fr:n('واژهٔ ارزیابانهٔ «enfin» می‌تواند انتظار یا رفع تأخیر را القا کند؛ این برداشت را از واقعیت تأییدشده و نظر کل جمعیت جدا کنید.','Le titre suggère une adhésion générale.','Le texte rapporte seulement la recommandation d’un comité.','اولی برداشت القایی و دومی آن چیزی است که منبع واقعاً گزارش می‌کند.',[['une présupposition','پیش‌فرض'],['une abstention','رأی ممتنع'],['une recommandation','توصیه']]),de:n('«endlich» می‌تواند انتظار و رفع تأخیر را القا کند؛ نتیجهٔ یک Ausschuss را بدون شواهد به تمام ساکنان نسبت ندهید.','Die Überschrift legt allgemeine Zustimmung nahe.','Der Text berichtet nur von einer Empfehlung des Ausschusses.','اولی برداشت القایی و دومی آن چیزی است که منبع واقعاً گزارش می‌کند.',[['eine Vorannahme','پیش‌فرض'],['eine Enthaltung','رأی ممتنع'],['eine Empfehlung','توصیه']]),es:n('«por fin» می‌تواند انتظار و پایان تأخیر را القا کند؛ توصیهٔ یک کمیته را بدون شاهد به رضایت همهٔ ساکنان تعمیم ندهید.','El titular sugiere una aceptación general.','El texto solo informa de una recomendación del comité.','اولی برداشت القایی و دومی آن چیزی است که منبع واقعاً گزارش می‌کند.',[['una presuposición','پیش‌فرض'],['una abstención','رأی ممتنع'],['una recomendación','توصیه']])},
speaking:'تیتر را از متن تفکیک کنید، یک پیش‌فرض و دو محدودیت شواهد را توضیح دهید و بازنویسی دقیق‌تری پیشنهاد کنید.',writing:'تحلیل رسانه‌ای بنویسید که زبان ارزشی، دادهٔ گزارش‌شده، اطلاعات نامعلوم و تیتر جایگزین را جدا کند.',steps:['تیتر و واژهٔ دارای بار نگرشی را نقل کنید.','گفتهٔ متن و اندازهٔ گروه را دقیق بیان کنید.','از تعمیم نظر کمیته و حدس دربارهٔ ممتنع‌ها بپرهیزید.','تیتر جایگزین و محدودیت باقی‌مانده را توضیح دهید.'],model:{fr:'Le titre « Enfin, les habitants acceptent le nouveau plan » suggère une adhésion générale après une opposition. Pourtant, le texte rapporte seulement qu’un comité de douze personnes recommande un essai ; deux membres se sont abstenus et aucune enquête générale n’est mentionnée. Un titre plus précis serait « Un comité recommande un essai du plan de circulation ». Même ainsi, les raisons des abstentions restent inconnues.',de:'Die Überschrift „Endlich akzeptieren die Bewohner den neuen Verkehrsplan“ legt eine allgemeine Zustimmung nach Widerstand nahe. Tatsächlich berichtet der Text nur, dass ein zwölfköpfiger Ausschuss einen Test empfiehlt; zwei Mitglieder enthielten sich und eine Befragung aller Bewohner wird nicht erwähnt. Präziser wäre „Ausschuss empfiehlt Test des Verkehrsplans“. Die Gründe für die Enthaltungen bleiben auch dann unbekannt.',es:'El titular «Por fin, los vecinos aceptan el nuevo plan» sugiere una aceptación general tras una oposición. Sin embargo, el texto solo informa de que un comité de doce personas recomienda una prueba; dos miembros se abstuvieron y no se menciona una encuesta general. Sería más preciso decir «Un comité recomienda probar el plan de tráfico». Aun así, los motivos de las abstenciones siguen siendo desconocidos.'}},
{id:'c1-subjectivity-evidence',level:'c1',section:'foundation',number:12,title:'وجه و درجهٔ اطمینان در گزارش',passage:{
fr:'Un comité étudie les effets d’un nouvel horaire d’ouverture à la bibliothèque. Il constate que le nombre d’entrées a augmenté pendant les quatre semaines de l’essai, mais il doute que cette hausse soit due uniquement au nouvel horaire. Pendant la même période, une exposition gratuite a également attiré des visiteurs. La responsable souhaite que l’équipe compare les données avec une période similaire et qu’elle interroge les usagers avant de conclure. Il est certain que le nombre d’entrées a augmenté ; il n’est pas établi que l’horaire soit la seule cause. Le comité recommande donc une analyse complémentaire, tout en rappelant que le choix final dépendra aussi des coûts et des besoins d’accès.',
de:'Ein Ausschuss untersucht die Wirkung neuer Öffnungszeiten einer Bibliothek. Die Zahl der Eintritte ist während des vierwöchigen Tests gestiegen. Die Vorsitzende sagt, die kostenlose Ausstellung im selben Zeitraum könnte zusätzliche Besucher angezogen haben; sie lässt offen, wie groß dieser Einfluss war. Ein Mitglied vermutet, dass die geänderten Öffnungszeiten ebenfalls eine Rolle gespielt haben müssen, räumt aber ein, dass diese Schlussfolgerung nicht bewiesen ist. Die Ausstellung allein kann nicht erklären, warum die Besuche an manchen Tagen anstiegen, doch weitere Daten fehlen. Der Ausschuss empfiehlt einen Vergleich mit einem ähnlichen Zeitraum und eine Befragung der Nutzer, bevor er Kosten, Zugang und Ursachen bewertet.',
es:'Un comité estudia los efectos de un nuevo horario de apertura en la biblioteca. Constata que el número de entradas ha aumentado durante las cuatro semanas de la prueba, pero duda de que ese incremento se deba únicamente al nuevo horario. Durante el mismo periodo, una exposición gratuita también atrajo visitantes. La responsable quiere que el equipo compare los datos con un periodo similar y que consulte a los usuarios antes de concluir. Es seguro que el número de entradas aumentó; no está demostrado que el horario sea la única causa. Por ello, el comité recomienda un análisis complementario y recuerda que la decisión final también dependerá de los costes y de las necesidades de acceso.'},
questions:[q('در دورهٔ آزمایش چه چیزی مشاهده شد؟',['افزایش تعداد ورودها','کاهش قطعی همهٔ هزینه‌ها','حذف نمایشگاه رایگان'],0,'تعداد ورودها در دورهٔ آزمایش افزایش یافت.',{fr:'le nombre d’entrées a augmenté pendant les quatre semaines',de:'Die Zahl der Eintritte ist während des vierwöchigen Tests gestiegen',es:'el número de entradas ha aumentado durante las cuatro semanas'}),q('چه عامل دیگری هم در همان دوره وجود داشت؟',['تعطیلی کامل کتابخانه','نمایشگاه رایگان','کاهش تعداد روزهای هفته'],1,'نمایشگاه رایگان نیز در همان دوره برقرار بود.',{fr:'une exposition gratuite a également attiré des visiteurs',de:'die kostenlose Ausstellung im selben Zeitraum',es:'una exposición gratuita también atrajo visitantes'}),q('کمیته پیش از نتیجه‌گیری چه پیشنهادی دارد؟',['اعلام علت قطعی بدون بررسی','حذف همهٔ نظرهای مراجعه‌کنندگان','مقایسهٔ دورهٔ مشابه و پرسش از استفاده‌کنندگان'],2,'مقایسه و پرسش از مراجعه‌کنندگان پیشنهاد شده است.',{fr:'compare les données avec une période similaire et qu’elle interroge les usagers',de:'einen Vergleich mit einem ähnlichen Zeitraum und eine Befragung der Nutzer',es:'compare los datos con un periodo similar y que consulte a los usuarios'})],
notes:{fr:n('در این بافت «constater que» گزارش یک واقعیت مشاهده‌شده را با indicatif می‌آورد؛ «douter que» و «souhaiter que» معمولاً subjonctif می‌گیرند. وجه به ساختار و نگرش وابسته است، نه صرفاً میزان حقیقت در جهان.', 'Le comité constate que les entrées ont augmenté.','Il doute que la hausse soit due uniquement à l’horaire.','اولی گزارش مشاهده با indicatif و دومی تردید با subjonctif است.',[['constater une hausse','مشاهدهٔ افزایش'],['douter d’une cause unique','تردید دربارهٔ علت یگانه'],['une analyse complémentaire','تحلیل تکمیلی']]),de:n('افعال وجهی در کاربرد ذهنی درجهٔ استنباط گوینده را نشان می‌دهند: «muss ... gespielt haben» استنباط قوی دربارهٔ گذشته است، نه الزام؛ «könnte ... angezogen haben» احتمال را بیان می‌کند. هیچ‌کدام به‌تنهایی شاهد قطعی نیست.','Die Öffnungszeiten müssen eine Rolle gespielt haben.','Die Ausstellung könnte zusätzliche Besucher angezogen haben.','اولی استنباط قوی‌تر و دومی احتمال دربارهٔ گذشته است.',[['eine Rolle gespielt haben','نقشی داشته بودن'],['zusätzliche Besucher anziehen','بازدیدکنندگان بیشتر جذب کردن'],['eine Schlussfolgerung überprüfen','بررسی نتیجه‌گیری']]),es:n('«constatar que» در گزارش مشاهده با indicativo می‌آید؛ «dudar de que» و «querer que» معمولاً subjuntivo می‌گیرند. انتخاب وجه به ساختار و نگرش بستگی دارد، نه صرفاً واقعیت بیرونی.', 'El comité constata que las entradas han aumentado.','Duda de que el incremento se deba solo al horario.','اولی گزارش مشاهده با indicativo و دومی تردید با subjuntivo است.',[['constatar un aumento','مشاهدهٔ افزایش'],['dudar de una causa única','تردید دربارهٔ علت یگانه'],['un análisis complementario','تحلیل تکمیلی']])},
speaking:'دادهٔ مشاهده‌شده را از فرض علت جدا کنید و در زبان انتخابی با ساختارهای درس درجهٔ اطمینان و بررسی لازم را بیان کنید.',writing:'یادداشتی برای کمیته بنویسید که مشاهده، تردید یا استنباط، علت جایگزین و بررسی آینده را تفکیک کند.',steps:['یافتهٔ مشاهده‌شده و بازهٔ زمانی را بیان کنید.','علت احتمالی و عامل جایگزین را از واقعیت تفکیک کنید.','ساختار وجه یا فعل وجهی مناسب زبان را به کار ببرید.','مقایسه و نظرسنجی پیش از تصمیم پیشنهاد کنید.'],model:{fr:'Le comité constate que les entrées ont augmenté pendant les quatre semaines de l’essai. Il doute toutefois que le nouvel horaire soit l’unique cause, car une exposition gratuite a eu lieu simultanément. Nous souhaitons que l’équipe compare les données avec une période similaire et interroge les usagers. Une hausse observée ne suffit pas à établir un lien causal ; les coûts et l’accès devront également être examinés.',de:'Die Eintritte sind während des vierwöchigen Tests gestiegen. Die Ausstellung könnte zusätzliche Besucher angezogen haben; auch die Öffnungszeiten müssen aus Sicht eines Mitglieds eine Rolle gespielt haben. Beide Einschätzungen bleiben jedoch unbelegte Schlussfolgerungen. Wir empfehlen, einen ähnlichen Zeitraum zu vergleichen und Nutzer zu befragen, bevor über Ursachen, Kosten und Zugang entschieden wird.',es:'El comité constata que las entradas han aumentado durante las cuatro semanas de prueba. Sin embargo, duda de que el nuevo horario sea la única causa, ya que hubo una exposición gratuita al mismo tiempo. Queremos que el equipo compare los datos con un periodo similar y consulte a los usuarios. Un aumento observado no basta para establecer una causa; también deberán examinarse los costes y el acceso.'}},
{id:'c1-source-synthesis',level:'c1',section:'foundation',number:21,title:'ترکیب دو منبع با روش و محدودیت متفاوت',passage:{
fr:'Un conseil local examine deux documents fictifs sur l’accès à un centre de santé. Le premier est un relevé des rendez-vous : sur deux cents consultations prévues en avril, trente ont été annulées avant le jour prévu. Ce relevé ne donne pas les raisons des annulations. Le second document résume vingt entretiens volontaires ; plusieurs personnes y évoquent des difficultés de transport, mais les participants ne représentent pas nécessairement tous les usagers. Une analyste évite de déduire que les trente annulations sont dues aux transports. Elle propose de rapprocher les deux sources en distinguant fréquence et expérience, puis de recueillir des données anonymes supplémentaires avant de recommander une modification des horaires.',
de:'Ein Gemeinderat prüft zwei fiktive Dokumente zum Zugang zu einem Gesundheitszentrum. Das erste ist eine Terminübersicht: Von zweihundert für April geplanten Terminen wurden dreißig vor dem vereinbarten Tag abgesagt. Die Übersicht nennt keine Gründe für die Absagen. Das zweite Dokument fasst zwanzig freiwillige Interviews zusammen; mehrere Personen erwähnen Verkehrsprobleme, doch die Befragten repräsentieren nicht unbedingt alle Nutzer. Eine Analystin vermeidet daher den Schluss, dass die dreißig Absagen auf den Verkehr zurückgehen. Sie schlägt vor, beide Quellen zusammenzuführen und dabei Häufigkeit und Erfahrung zu unterscheiden sowie zusätzliche anonyme Daten zu erheben, bevor eine Änderung der Öffnungszeiten empfohlen wird.',
es:'Un consejo local examina dos documentos ficticios sobre el acceso a un centro de salud. El primero es un registro de citas: de doscientas consultas previstas en abril, treinta se cancelaron antes del día acordado. El registro no indica los motivos de las cancelaciones. El segundo documento resume veinte entrevistas voluntarias; varias personas mencionan dificultades de transporte, pero los participantes no representan necesariamente a todos los usuarios. Una analista evita concluir que las treinta cancelaciones se debieron al transporte. Propone relacionar las dos fuentes distinguiendo frecuencia y experiencia, y recoger más datos anónimos antes de recomendar un cambio de horario.'},
questions:[q('منبع اول چه عددی را گزارش می‌کند؟',['۳۰ لغو پیش از موعد از ۲۰۰ نوبت','۲۰ لغو از ۳۰ نوبت','۲۰۰ مصاحبهٔ داوطلبانه'],0,'در منبع اول ۳۰ نوبت از ۲۰۰ نوبت لغو شد.',{fr:'sur deux cents consultations prévues en avril, trente ont été annulées',de:'Von zweihundert für April geplanten Terminen wurden dreißig',es:'de doscientas consultas previstas en abril, treinta se cancelaron'}),q('محدودیت مصاحبه‌ها چیست؟',['هیچ‌کس مسئلهٔ رفت‌وآمد را مطرح نکرد','داوطلبان لزوماً نمایندهٔ همه نیستند','مصاحبه‌ها دلیل تمام لغوها را ثابت می‌کنند'],1,'شرکت‌کنندگان داوطلب لزوماً نمایندهٔ تمام مراجعه‌کنندگان نیستند.',{fr:'les participants ne représentent pas nécessairement tous les usagers',de:'die Befragten repräsentieren nicht unbedingt alle Nutzer',es:'los participantes no representan necesariamente a todos los usuarios'}),q('تحلیلگر از چه نتیجه‌گیری پرهیز می‌کند؟',['وجود دو منبع با روش متفاوت','وجود مشکل حمل‌ونقل در برخی مصاحبه‌ها','انتساب هر ۳۰ لغو به حمل‌ونقل'],2,'منابع ثابت نمی‌کنند که همهٔ لغوها به حمل‌ونقل مربوط‌اند.',{fr:'évite de déduire que les trente annulations sont dues aux transports',de:'vermeidet daher den Schluss, dass die dreißig Absagen auf den Verkehr zurückgehen',es:'evita concluir que las treinta cancelaciones se debieron al transporte'})],
notes:{fr:n('ترکیب منابع به معنی ادغام بی‌قید داده‌ها نیست؛ منشأ، روش، دامنه و محدودیت هر منبع را حفظ کنید و از هم‌زمانی، علت نتیجه نگیرید.','Le relevé indique trente annulations, sans en préciser les motifs.','Les entretiens évoquent le transport, sans représenter tous les usagers.','اولی شمارش و دومی تجربهٔ گروهی داوطلب است.',[['un relevé de rendez-vous','ثبت نوبت‌ها'],['un entretien volontaire','مصاحبهٔ داوطلبانه'],['attribuer une cause','نسبت دادن علت']]),de:n('هنگام ترکیب، نوع و محدودهٔ هر منبع را حفظ کنید؛ گزارش فراوانی و تجربهٔ داوطلبان به‌تنهایی رابطهٔ علّی را ثابت نمی‌کند.','Die Übersicht nennt dreißig Absagen, aber keine Gründe.','Die Interviews nennen Verkehrsprobleme, repräsentieren aber nicht alle Nutzer.','اولی شمارش و دومی تجربهٔ گروهی داوطلب است.',[['eine Terminübersicht','ثبت نوبت‌ها'],['ein freiwilliges Interview','مصاحبهٔ داوطلبانه'],['eine Ursache zuschreiben','نسبت دادن علت']]),es:n('هنگام ترکیب منابع، روش و محدودیت هر کدام را مشخص کنید؛ شمارش لغوها و تجربهٔ داوطلبان به‌تنهایی علت همهٔ لغوها را ثابت نمی‌کند.','El registro indica treinta cancelaciones, pero no sus motivos.','Las entrevistas mencionan el transporte, sin representar a todos los usuarios.','اولی شمارش و دومی تجربهٔ گروهی داوطلب است.',[['un registro de citas','ثبت نوبت‌ها'],['una entrevista voluntaria','مصاحبهٔ داوطلبانه'],['atribuir una causa','نسبت دادن علت']])},
speaking:'برای شورا دو منبع، تفاوت روش، آنچه می‌توان و نمی‌توان نتیجه گرفت و دادهٔ اضافی لازم را توضیح دهید.',writing:'ترکیبی کوتاه از دو منبع با انتساب داده‌ها و محدودیت‌های روش‌شناختی بنویسید.',steps:['برای هر منبع روش و دامنه را مشخص کنید.','عددهای منبع اول و تجربهٔ منبع دوم را جدا گزارش کنید.','رابطهٔ علّی اثبات‌نشده و محدودیت نمایندگی را توضیح دهید.','گردآوری دادهٔ ناشناس پیش از تصمیم را پیشنهاد کنید.'],model:{fr:'Le relevé indique que trente des deux cents rendez-vous prévus en avril ont été annulés, sans préciser pourquoi. Dans vingt entretiens volontaires, plusieurs personnes évoquent des difficultés de transport, mais ces participants ne représentent pas nécessairement tous les usagers. Ces sources suggèrent une question à approfondir, non la cause des trente annulations. Des données anonymes supplémentaires seraient nécessaires avant de recommander un changement d’horaires.',de:'Laut Terminübersicht wurden dreißig von zweihundert Aprilterminen abgesagt; Gründe werden nicht genannt. In zwanzig freiwilligen Interviews berichten mehrere Personen über Verkehrsprobleme, doch die Befragten repräsentieren nicht unbedingt alle Nutzer. Zusammen zeigen die Quellen eine offene Frage, nicht die Ursache aller dreißig Absagen. Vor einer Empfehlung zu den Öffnungszeiten sollten weitere anonyme Daten erhoben werden.',es:'Según el registro, se cancelaron treinta de las doscientas citas de abril, sin que consten los motivos. En veinte entrevistas voluntarias, varias personas mencionan dificultades de transporte, pero no representan necesariamente a todos los usuarios. Ambas fuentes plantean una cuestión que investigar, no demuestran la causa de las treinta cancelaciones. Antes de recomendar un cambio de horario habría que recoger más datos anónimos.'}},

{id:'c1-focus-contrast',level:'c1',section:'foundation',number:9,title:'تأکید بر عامل، موضوع و زمان',passage:{
fr:'Lors d’une réunion sur la rénovation d’un théâtre, une responsable corrige plusieurs malentendus. Ce sont les techniciens, et non les élus, qui ont signalé le risque lié au système électrique. C’est la sécurité du public que le groupe examine en priorité, et non le choix des couleurs. Quant au calendrier, c’est en septembre que les travaux pourraient commencer, à condition que le financement soit confirmé. Une élue demande si ces formulations impliquent que les autres aspects sont sans importance. La responsable répond que non : elles servent à identifier les priorités et les sources d’information, sans exclure une discussion ultérieure sur l’esthétique et le budget. Elle invite ensuite chacun à vérifier le compte rendu avant sa diffusion.',
de:'In einer Sitzung über die Renovierung eines Theaters korrigiert eine Verantwortliche mehrere Missverständnisse. Es waren die Techniker, nicht die gewählten Vertreter, die auf das Risiko der elektrischen Anlage hingewiesen haben. Die Sicherheit des Publikums ist es, die die Gruppe vorrangig prüft, nicht die Farbwahl. Was den Zeitplan betrifft, könnten die Arbeiten erst im September beginnen, sofern die Finanzierung bestätigt wird. Eine Vertreterin fragt, ob diese Formulierungen bedeuten, dass andere Aspekte unwichtig seien. Die Verantwortliche verneint: Sie dienen dazu, Prioritäten und Informationsquellen zu benennen, ohne spätere Gespräche über Ästhetik und Budget auszuschließen. Anschließend bittet sie alle, das Protokoll vor der Weitergabe zu prüfen.',
es:'En una reunión sobre la renovación de un teatro, una responsable corrige varios malentendidos. Fueron los técnicos, y no los representantes electos, quienes señalaron el riesgo de la instalación eléctrica. Es la seguridad del público lo que el grupo examina prioritariamente, y no la elección de colores. En cuanto al calendario, sería en septiembre cuando podrían comenzar las obras, siempre que se confirme la financiación. Una representante pregunta si estas formulaciones implican que los demás aspectos no son importantes. La responsable responde que no: sirven para identificar prioridades y fuentes de información sin excluir un debate posterior sobre la estética y el presupuesto. Después pide a todos que revisen el acta antes de su difusión.'},
questions:[q('چه کسانی خطر سیستم برق را مطرح کردند؟',['تکنسین‌ها','نمایندگان منتخب','تماشاگران'],0,'تکنسین‌ها خطر را گزارش کردند.',{fr:'Ce sont les techniciens, et non les élus, qui ont signalé',de:'Es waren die Techniker, nicht die gewählten Vertreter',es:'Fueron los técnicos, y no los representantes electos, quienes señalaron'}),q('اولویت بررسی گروه چیست؟',['انتخاب رنگ','ایمنی مخاطبان','خرید لباس جدید'],1,'گروه ابتدا ایمنی مخاطبان را بررسی می‌کند.',{fr:'C’est la sécurité du public que le groupe examine en priorité',de:'Die Sicherheit des Publikums ist es, die die Gruppe vorrangig prüft',es:'Es la seguridad del público lo que el grupo examina prioritariamente'}),q('آیا شروع کار در سپتامبر قطعی است؟',['بله بدون شرط','بله چون همهٔ بودجه پرداخت شده','خیر، مشروط به تأیید تأمین مالی است'],2,'شروع سپتامبر مشروط به تأیید تأمین مالی است.',{fr:'en septembre que les travaux pourraient commencer, à condition que le financement soit confirmé',de:'erst im September beginnen, sofern die Finanzierung bestätigt wird',es:'en septiembre cuando podrían comenzar las obras, siempre que se confirme la financiación'})],
notes:{fr:n('ساختار شکافتهٔ «c’est ... qui» فاعل و «c’est ... que» مفعول یا جزء دیگری را برجسته می‌کند؛ تأکید الزاماً به معنی حذف اهمیت سایر عوامل نیست.','Ce sont les techniciens qui ont signalé le risque.','C’est la sécurité que le groupe examine.','در اولی عامل و در دومی موضوع بررسی برجسته شده است.',[['signaler un risque','گزارش خطر'],['examiner en priorité','در اولویت بررسی کردن'],['sous réserve de financement','مشروط به تأمین مالی']]),de:n('Spaltsatz با «es ist/war ... der/die/das» می‌تواند یک جزء را در تقابل برجسته کند؛ شکل موصولی با اسم برجسته هماهنگ می‌شود. ساختارهای تأکیدی در آلمانی بسته به بافت می‌توانند رسمی یا نشاندار باشند.','Es waren die Techniker, die das Risiko meldeten.','Die Sicherheit ist es, die die Gruppe prüft.','در اولی عامل و در دومی موضوع بررسی برجسته شده است.',[['ein Risiko melden','گزارش خطر'],['vorrangig prüfen','در اولویت بررسی کردن'],['vorbehaltlich der Finanzierung','مشروط به تأمین مالی']]),es:n('جمله‌های شکافته با «ser ... quien/quienes» برای عامل و «ser ... lo que» برای موضوع می‌توانند کانون جمله را برجسته کنند؛ زمان و شمار را با ساختار هماهنگ کنید.','Fueron los técnicos quienes señalaron el riesgo.','Es la seguridad lo que examina el grupo.','در اولی عامل و در دومی موضوع بررسی برجسته شده است.',[['señalar un riesgo','گزارش خطر'],['examinar prioritariamente','در اولویت بررسی کردن'],['siempre que haya financiación','مشروط به تأمین مالی']])},
speaking:'سوءتفاهم‌های جلسه را اصلاح کنید؛ عامل گزارش خطر، اولویت و زمان مشروط را با ساختارهای تأکیدی بیان کنید.',writing:'یادداشتی بنویسید که با تأکید، عامل، موضوع و زمان را بدون حذف شرط یا بی‌اهمیت جلوه دادن سایر مسائل روشن کند.',steps:['عامل گزارش خطر را در تقابل با برداشت نادرست معرفی کنید.','موضوع بررسی اولویت‌دار را برجسته کنید.','زمان مشروط به تأمین مالی را توضیح دهید.','جایگاه بحث بعدی و بررسی صورت‌جلسه را اضافه کنید.'],model:{fr:'Ce sont les techniciens, et non les élus, qui ont signalé le risque électrique. C’est la sécurité du public que nous examinons en priorité. C’est en septembre que les travaux pourraient commencer, à condition que le financement soit confirmé. Cela ne signifie pas que les couleurs ou le budget sont sans importance : nous les examinerons aussi. Merci de vérifier le compte rendu avant sa diffusion.',de:'Es waren die Techniker und nicht die gewählten Vertreter, die das elektrische Risiko meldeten. Die Sicherheit des Publikums ist es, die wir vorrangig prüfen. Die Arbeiten könnten erst im September beginnen, sofern die Finanzierung bestätigt wird. Das bedeutet nicht, dass Farben und Budget unwichtig sind; wir werden auch darüber sprechen. Bitte prüfen Sie das Protokoll vor der Weitergabe.',es:'Fueron los técnicos, y no los representantes electos, quienes señalaron el riesgo eléctrico. Es la seguridad del público lo que examinamos prioritariamente. Sería en septiembre cuando podrían comenzar las obras, siempre que se confirme la financiación. Eso no significa que los colores o el presupuesto no importen: también los debatiremos. Revisen el acta antes de difundirla, por favor.'}},
{id:'c1-diplomatic-feedback',level:'c1',section:'survival',number:10,title:'بازخورد دقیق با تفکیک مشاهده و پیشنهاد',passage:{
fr:'Après une présentation destinée au conseil, Sofia demande un retour à son collègue Marc. Il souligne d’abord que les objectifs et le calendrier étaient clairement présentés. Il précise ensuite qu’à deux reprises les graphiques ne mentionnaient pas la taille de l’échantillon, ce qui rendait difficile l’interprétation des pourcentages. Plutôt que de juger la compétence de Sofia, il lui propose d’ajouter le nombre de réponses et une phrase sur les limites des données. Sofia explique que l’information figurait dans une annexe, mais reconnaît qu’elle n’était pas visible sur les diapositives. Ils conviennent de revoir ensemble les graphiques avant la prochaine réunion ; Marc lui enverra les exemples précis ce soir.',
de:'Nach einer Präsentation für den Rat bittet Sofia ihren Kollegen Marc um Rückmeldung. Er hebt zunächst hervor, dass Ziele und Zeitplan klar dargestellt waren. Anschließend erklärt er, dass auf zwei Grafiken die Stichprobengröße fehlte, was die Interpretation der Prozentzahlen erschwerte. Anstatt Sofias Kompetenz zu beurteilen, schlägt er vor, die Zahl der Antworten und einen Satz über die Grenzen der Daten zu ergänzen. Sofia erklärt, dass die Information in einem Anhang stand, räumt aber ein, dass sie auf den Folien nicht sichtbar war. Sie vereinbaren, die Grafiken vor der nächsten Sitzung gemeinsam zu prüfen; Marc schickt ihr die konkreten Beispiele noch heute Abend.',
es:'Después de una presentación ante el consejo, Sofía pide comentarios a su compañero Marc. Él destaca primero que los objetivos y el calendario se presentaron con claridad. A continuación precisa que en dos gráficos no figuraba el tamaño de la muestra, lo que dificultaba interpretar los porcentajes. En vez de juzgar la competencia de Sofía, propone añadir el número de respuestas y una frase sobre las limitaciones de los datos. Sofía explica que la información estaba en un anexo, pero reconoce que no se veía en las diapositivas. Acuerdan revisar juntos los gráficos antes de la próxima reunión; Marc le enviará los ejemplos concretos esta noche.'},
questions:[q('نکتهٔ مثبت مطرح‌شده چیست؟',['ارائهٔ روشن هدف‌ها و زمان‌بندی','وجود اندازهٔ نمونه در همهٔ نمودارها','پایان کامل بازبینی'],0,'هدف‌ها و زمان‌بندی روشن ارائه شده‌اند.',{fr:'les objectifs et le calendrier étaient clairement présentés',de:'Ziele und Zeitplan klar dargestellt waren',es:'los objetivos y el calendario se presentaron con claridad'}),q('مشکل مشخص دو نمودار چیست؟',['نبود عنوان پروژه','ذکر نشدن اندازهٔ نمونه','نامعلوم بودن تاریخ جلسه'],1,'اندازهٔ نمونه در دو نمودار مشخص نبود.',{fr:'à deux reprises les graphiques ne mentionnaient pas la taille de l’échantillon',de:'auf zwei Grafiken die Stichprobengröße fehlte',es:'en dos gráficos no figuraba el tamaño de la muestra'}),q('گام بعدی توافق‌شده چیست؟',['ارسال ارائه بدون تغییر','حذف تمام درصدها بدون بررسی','بازبینی مشترک نمودارها و ارسال مثال‌های مشخص'],2,'آنها بازبینی مشترک را توافق می‌کنند و مارک مثال‌ها را می‌فرستد.',{fr:'revoir ensemble les graphiques avant la prochaine réunion ; Marc lui enverra les exemples précis',de:'die Grafiken vor der nächsten Sitzung gemeinsam zu prüfen; Marc schickt ihr die konkreten Beispiele',es:'revisar juntos los gráficos antes de la próxima reunión; Marc le enviará los ejemplos concretos'})],
notes:{fr:n('بازخورد دیپلماتیک مشاهدهٔ قابل بررسی، اثر آن و پیشنهاد عملی را از قضاوت شخصیتی جدا می‌کند؛ شرطی می‌تواند پیشنهاد را ملایم‌تر کند.','Deux graphiques ne mentionnaient pas la taille de l’échantillon.','Nous pourrions ajouter le nombre de réponses sur chaque diapositive.','اولی مشاهدهٔ مشخص و دومی پیشنهاد قابل اقدام است.',[['une taille d’échantillon','اندازهٔ نمونه'],['une limite des données','محدودیت داده‌ها'],['une suggestion concrète','پیشنهاد مشخص']]),de:n('بازخورد سازنده مشاهده، اثر و پیشنهاد عملی را جدا می‌کند؛ Konjunktiv II می‌تواند پیشنهاد را ملایم کند بدون اینکه مشکل را مبهم سازد.','Auf zwei Grafiken fehlte die Stichprobengröße.','Wir könnten die Zahl der Antworten auf den Folien ergänzen.','اولی مشاهدهٔ مشخص و دومی پیشنهاد قابل اقدام است.',[['eine Stichprobengröße','اندازهٔ نمونه'],['eine Grenze der Daten','محدودیت داده‌ها'],['ein konkreter Vorschlag','پیشنهاد مشخص']]),es:n('مشاهدهٔ قابل بررسی، اثر و پیشنهاد عملی را از قضاوت دربارهٔ فرد جدا کنید؛ condicional می‌تواند پیشنهاد را دیپلماتیک کند.','En dos gráficos no figuraba el tamaño de la muestra.','Podríamos añadir el número de respuestas en las diapositivas.','اولی مشاهدهٔ مشخص و دومی پیشنهاد قابل اقدام است.',[['el tamaño de la muestra','اندازهٔ نمونه'],['una limitación de los datos','محدودیت داده‌ها'],['una sugerencia concreta','پیشنهاد مشخص']])},
speaking:'به همکار فرضی بازخورد بدهید: ابتدا نکتهٔ مثبت، سپس دو مشاهدهٔ مشخص، اثر و پیشنهاد را بیان کنید و نظر او را بپرسید.',writing:'پیامی دیپلماتیک دربارهٔ دو نمودار بنویسید که مشاهده را از قضاوت شخصی جدا و اقدام بعدی را مشخص کند.',steps:['نکتهٔ مثبت را به‌طور مشخص بیان کنید.','مشاهده و اثر آن بر فهم درصدها را توضیح دهید.','پیشنهاد و فرصت پاسخ همکار را اضافه کنید.','بازبینی مشترک و ارسال مثال‌ها را تأیید کنید.'],model:{fr:'Merci pour la présentation : les objectifs et le calendrier étaient clairs. J’ai remarqué que deux graphiques ne mentionnaient pas la taille de l’échantillon, ce qui peut rendre les pourcentages difficiles à interpréter. Pourrions-nous ajouter le nombre de réponses et une phrase sur les limites ? Je sais que ces informations figurent dans l’annexe. Je vous enverrai les exemples ce soir et nous pourrons les revoir ensemble avant la prochaine réunion.',de:'Vielen Dank für die Präsentation; Ziele und Zeitplan waren klar. Mir ist aufgefallen, dass auf zwei Grafiken die Stichprobengröße fehlte, wodurch die Prozentzahlen schwerer einzuordnen sind. Könnten wir die Zahl der Antworten und einen Satz zu den Grenzen ergänzen? Ich weiß, dass die Angaben im Anhang stehen. Ich schicke dir die Beispiele heute Abend, damit wir die Grafiken vor der nächsten Sitzung gemeinsam prüfen können.',es:'Gracias por la presentación: los objetivos y el calendario estaban claros. Observé que en dos gráficos no figuraba el tamaño de la muestra, lo que puede dificultar la interpretación de los porcentajes. ¿Podríamos añadir el número de respuestas y una frase sobre las limitaciones? Sé que la información está en el anexo. Te enviaré los ejemplos esta noche y podremos revisar los gráficos juntos antes de la próxima reunión.'}},

{id:'c1-abstract-fairness',level:'c1',section:'foundation',number:1,title:'توضیح دقیق مفهوم عدالت در تخصیص',passage:{
fr:'Une commission doit répartir un budget limité entre plusieurs bibliothèques. Avant de choisir une méthode, sa présidente distingue deux conceptions de l’équité. Une répartition égale donnerait la même somme à chaque établissement ; une répartition fondée sur les besoins tiendrait compte, par exemple, du nombre d’usagers et de l’état des locaux. La seconde n’est pas automatiquement plus juste : elle dépend du choix des critères et de la qualité des données. Une directrice rappelle qu’une petite bibliothèque isolée peut avoir des coûts fixes élevés malgré un faible nombre d’usagers. La commission décide donc de publier les critères envisagés et de consulter les établissements avant de calculer plusieurs scénarios. Aucun montant final n’est encore attribué.',
de:'Eine Kommission muss ein begrenztes Budget auf mehrere Bibliotheken verteilen. Vor der Wahl einer Methode unterscheidet ihre Vorsitzende zwei Vorstellungen von Gerechtigkeit. Eine gleiche Verteilung gäbe jeder Einrichtung denselben Betrag; eine bedarfsorientierte Verteilung würde zum Beispiel die Zahl der Nutzer und den Zustand der Räume berücksichtigen. Die zweite ist nicht automatisch gerechter: Sie hängt von der Wahl der Kriterien und der Qualität der Daten ab. Eine Leiterin weist darauf hin, dass eine kleine abgelegene Bibliothek trotz geringer Nutzerzahlen hohe Fixkosten haben kann. Die Kommission beschließt daher, die vorgesehenen Kriterien zu veröffentlichen und die Einrichtungen zu befragen, bevor sie mehrere Szenarien berechnet. Endgültige Beträge wurden noch nicht zugeteilt.',
es:'Una comisión debe distribuir un presupuesto limitado entre varias bibliotecas. Antes de elegir un método, su presidenta distingue dos concepciones de la equidad. Un reparto igualitario daría la misma cantidad a cada centro; uno basado en las necesidades tendría en cuenta, por ejemplo, el número de usuarios y el estado de los locales. El segundo no es automáticamente más justo: depende de la elección de los criterios y de la calidad de los datos. Una directora recuerda que una biblioteca pequeña y aislada puede tener costes fijos altos a pesar de contar con pocos usuarios. Por ello, la comisión decide publicar los criterios previstos y consultar a los centros antes de calcular varios escenarios. Todavía no se han asignado cantidades definitivas.'},
questions:[q('تفاوت دو شیوهٔ تخصیص چیست؟',['مبلغ برابر در برابر تخصیص بر اساس نیاز','بودجهٔ یکسان در برابر حذف تمام کتابخانه‌ها','تصمیم قطعی در برابر رأی‌گیری انجام‌شده'],0,'یکی مبلغ برابر و دیگری معیارهای نیاز را در نظر می‌گیرد.',{fr:'la même somme à chaque établissement ; une répartition fondée sur les besoins',de:'jeder Einrichtung denselben Betrag; eine bedarfsorientierte Verteilung',es:'la misma cantidad a cada centro; uno basado en las necesidades'}),q('چرا کتابخانهٔ کوچک ممکن است به توجه بیشتری نیاز داشته باشد؟',['چون هیچ هزینه‌ای ندارد','ممکن است با وجود کاربران کم هزینهٔ ثابت بالایی داشته باشد','چون بودجهٔ نهایی را دریافت کرده است'],1,'کتابخانهٔ کوچک و دورافتاده ممکن است هزینهٔ ثابت بالا داشته باشد.',{fr:'une petite bibliothèque isolée peut avoir des coûts fixes élevés malgré un faible nombre d’usagers',de:'eine kleine abgelegene Bibliothek trotz geringer Nutzerzahlen hohe Fixkosten haben kann',es:'una biblioteca pequeña y aislada puede tener costes fijos altos a pesar de contar con pocos usuarios'}),q('وضعیت مبالغ نهایی چیست؟',['همه پرداخت شده‌اند','فقط به کتابخانهٔ مرکزی اختصاص یافته‌اند','هنوز تخصیص نهایی صورت نگرفته است'],2,'هنوز مبلغ نهایی تخصیص نیافته است.',{fr:'Aucun montant final n’est encore attribué',de:'Endgültige Beträge wurden noch nicht zugeteilt',es:'Todavía no se han asignado cantidades definitivas'})],
notes:{fr:n('مفهوم انتزاعی را تعریف و دو برداشت را با معیار و مثال عینی مقایسه کنید؛ از برابر دانستن برابری صوری و عدالت بدون توضیح پرهیز کنید.','Une répartition égale donne la même somme à chaque établissement.','Une répartition selon les besoins dépend des critères retenus.','اولی تعریف برابری مبلغ و دومی رویکرد مشروط به معیار است.',[['une répartition équitable','تخصیص منصفانه'],['des coûts fixes','هزینه‌های ثابت'],['des critères transparents','معیارهای شفاف']]),de:n('مفهوم انتزاعی را با تعریف‌های رقیب و مثال روشن کنید؛ Gerechtigkeit و gleiche Beträge الزاماً یکسان نیستند.','Eine gleiche Verteilung gibt jeder Einrichtung denselben Betrag.','Eine bedarfsorientierte Verteilung hängt von den Kriterien ab.','اولی تعریف برابری مبلغ و دومی رویکرد مشروط به معیار است.',[['eine gerechte Verteilung','تخصیص منصفانه'],['Fixkosten','هزینه‌های ثابت'],['transparente Kriterien','معیارهای شفاف']]),es:n('با تعریف، تقابل و مثال، مفهوم انتزاعی را روشن کنید؛ igualdad de cantidades و equidad بر اساس نیاز همواره یکی نیستند.','Un reparto igualitario da la misma cantidad a cada centro.','Un reparto según las necesidades depende de los criterios elegidos.','اولی تعریف برابری مبلغ و دومی رویکرد مشروط به معیار است.',[['un reparto equitativo','تخصیص منصفانه'],['costes fijos','هزینه‌های ثابت'],['criterios transparentes','معیارهای شفاف']])},
speaking:'دو برداشت از عدالت را تعریف کنید، با مثال کتابخانهٔ کوچک محدودیت معیار تعداد کاربران را توضیح دهید و راه تصمیم‌گیری پیشنهاد کنید.',writing:'یادداشتی برای کمیسیون بنویسید که دو تعریف، مثال نقض ساده و روش انتخاب معیارها را بیان کند.',steps:['مسئلهٔ بودجه و دو تعریف را معرفی کنید.','معیارهای احتمالی نیاز را توضیح دهید.','مثال هزینهٔ ثابت و محدودیت داده را بیان کنید.','مشورت و سناریوهای جایگزین پیش از تصمیم را پیشنهاد دهید.'],model:{fr:'Une répartition égale attribuerait la même somme à chaque bibliothèque, tandis qu’une répartition fondée sur les besoins utiliserait des critères comme l’état des locaux et le nombre d’usagers. Cette seconde méthode n’est juste que si ses critères et ses données sont pertinents. Une petite bibliothèque isolée peut avoir des coûts fixes élevés. La commission devrait publier les critères, consulter les établissements et comparer plusieurs scénarios avant d’attribuer les montants.',de:'Eine gleiche Verteilung gäbe jeder Bibliothek denselben Betrag; eine bedarfsorientierte Verteilung berücksichtigte Kriterien wie Raumzustand und Nutzerzahl. Die zweite Methode ist nur dann gerecht, wenn Kriterien und Daten geeignet sind. Eine kleine abgelegene Bibliothek kann hohe Fixkosten haben. Die Kommission sollte ihre Kriterien veröffentlichen, die Einrichtungen befragen und mehrere Szenarien vergleichen, bevor sie Beträge zuteilt.',es:'Un reparto igualitario daría la misma cantidad a cada biblioteca, mientras que uno basado en las necesidades usaría criterios como el estado de los locales y el número de usuarios. Este segundo método solo es justo si los criterios y datos son adecuados. Una biblioteca pequeña y aislada puede tener costes fijos altos. La comisión debería publicar los criterios, consultar a los centros y comparar varios escenarios antes de asignar cantidades.'}},
{id:'c1-formal-correspondence',level:'c1',section:'survival',number:27,title:'مکاتبهٔ رسمی با درخواست و پیگیری مشروط',passage:{
fr:'Objet : demande de précisions concernant la convention de formation. Madame, Monsieur, notre association a reçu votre projet de convention le 8 mars et vous remercie de cet envoi. Avant de le soumettre à notre conseil, nous souhaiterions clarifier deux points. L’article 4 prévoit une modification du calendrier en cas d’indisponibilité de la salle, mais ne précise pas le délai de préavis. Par ailleurs, l’annexe financière indique les frais de location sans préciser si le matériel est inclus. Pourriez-vous nous transmettre ces précisions et, si nécessaire, une version actualisée avant le 20 mars ? Nous ne sommes pas encore en mesure de confirmer la signature ; celle-ci dépendra de l’examen par notre conseil. Nous restons à votre disposition pour un échange. Cordialement, Samira Benali.',
de:'Betreff: Bitte um Klärung der Fortbildungsvereinbarung. Sehr geehrte Damen und Herren, unser Verein hat Ihren Vertragsentwurf am 8. März erhalten und dankt Ihnen dafür. Bevor wir ihn unserem Vorstand vorlegen, möchten wir zwei Punkte klären. Artikel 4 sieht bei Nichtverfügbarkeit des Raums eine Änderung des Zeitplans vor, nennt aber keine Vorankündigungsfrist. Außerdem enthält die finanzielle Anlage die Mietkosten, ohne anzugeben, ob die Ausstattung enthalten ist. Könnten Sie uns diese Informationen und gegebenenfalls eine aktualisierte Fassung vor dem 20. März zusenden? Eine Unterzeichnung können wir noch nicht bestätigen; sie hängt von der Prüfung durch unseren Vorstand ab. Für ein Gespräch stehen wir Ihnen gern zur Verfügung. Mit freundlichen Grüßen, Samira Benali.',
es:'Asunto: solicitud de aclaraciones sobre el convenio de formación. Estimados señores: nuestra asociación recibió su borrador de convenio el 8 de marzo y les agradece el envío. Antes de presentarlo a nuestro consejo, quisiéramos aclarar dos puntos. El artículo 4 prevé una modificación del calendario si la sala no está disponible, pero no especifica el plazo de preaviso. Además, el anexo financiero indica los gastos de alquiler sin aclarar si el material está incluido. ¿Podrían facilitarnos estas precisiones y, si fuera necesario, una versión actualizada antes del 20 de marzo? Todavía no podemos confirmar la firma, que dependerá de la revisión por nuestro consejo. Quedamos a su disposición para conversar. Atentamente, Samira Benali.'},
questions:[q('دو نکتهٔ نیازمند توضیح کدام‌اند؟',['مهلت اطلاع قبلی و گنجانده شدن تجهیزات در هزینه','فقط نام انجمن و رنگ سالن','تاریخ برگزاری جلسهٔ سال گذشته'],0,'نامه دربارهٔ مهلت اطلاع قبلی و تجهیزات در هزینه می‌پرسد.',{fr:'ne précise pas le délai de préavis. Par ailleurs, l’annexe financière indique les frais de location sans préciser si le matériel est inclus',de:'nennt aber keine Vorankündigungsfrist. Außerdem enthält die finanzielle Anlage die Mietkosten, ohne anzugeben, ob die Ausstattung enthalten ist',es:'no especifica el plazo de preaviso. Además, el anexo financiero indica los gastos de alquiler sin aclarar si el material está incluido'}),q('چه زمانی برای دریافت توضیح درخواست شده است؟',['۸ مارس','پیش از ۲۰ مارس','پس از امضای قرارداد'],1,'نامه درخواست پاسخ پیش از ۲۰ مارس دارد.',{fr:'avant le 20 mars',de:'vor dem 20. März',es:'antes del 20 de marzo'}),q('وضعیت امضا چیست؟',['قطعی و انجام شده است','طرف مقابل آن را تضمین کرده است','هنوز تأیید نشده و وابسته به بررسی شوراست'],2,'امضا هنوز تأیید نشده و به بررسی شورا بستگی دارد.',{fr:'Nous ne sommes pas encore en mesure de confirmer la signature',de:'Eine Unterzeichnung können wir noch nicht bestätigen',es:'Todavía no podemos confirmar la firma'})],
notes:{fr:n('نامهٔ رسمی با موضوع، زمینهٔ مستند، سؤال‌های دقیق، مهلت و وضعیت تصمیم همراه است؛ «nous souhaiterions» درخواست را مؤدبانه می‌کند و امضا را قطعی نمی‌سازد.','Nous souhaiterions clarifier deux points avant l’examen du conseil.','La signature dépendra de cet examen.','اولی درخواست و دومی محدودیت تصمیم است.',[['un projet de convention','پیش‌نویس توافق'],['un délai de préavis','مهلت اطلاع قبلی'],['une version actualisée','نسخهٔ به‌روز']]),de:n('در نامهٔ رسمی Betreff، ارجاع دقیق، درخواست و مهلت مشخص را با Sie و Konjunktiv II همراه کنید؛ وابستگی امضا به بررسی را حفظ کنید.','Wir möchten vor der Prüfung zwei Punkte klären.','Die Unterzeichnung hängt von der Prüfung des Vorstands ab.','اولی درخواست و دومی محدودیت تصمیم است.',[['ein Vertragsentwurf','پیش‌نویس توافق'],['eine Vorankündigungsfrist','مهلت اطلاع قبلی'],['eine aktualisierte Fassung','نسخهٔ به‌روز']]),es:n('در نامهٔ رسمی موضوع و ارجاع، درخواست روشن با condicional و مهلت را بیاورید؛ تصمیم معلق را قطعی اعلام نکنید.','Quisiéramos aclarar dos puntos antes de la revisión.','La firma dependerá de la revisión del consejo.','اولی درخواست و دومی محدودیت تصمیم است.',[['un borrador de convenio','پیش‌نویس توافق'],['un plazo de preaviso','مهلت اطلاع قبلی'],['una versión actualizada','نسخهٔ به‌روز']])},
speaking:'در تماس رسمی دو ابهام توافق و مهلت پاسخ را مطرح کنید و توضیح دهید چرا امضا هنوز تأیید نشده است.',writing:'نامه‌ای رسمی به طرف مقابل بنویسید که ارجاع، دو سؤال، مهلت، شرایط بررسی و پایان محترمانه داشته باشد.',steps:['موضوع و تاریخ دریافت را بیان کنید.','هر دو ابهام را با ارجاع مشخص توضیح دهید.','پاسخ و نسخهٔ احتمالی جدید را با مهلت بخواهید.','شرط بررسی شورا و پایان رسمی را اضافه کنید.'],model:{fr:'Objet : précisions sur la convention de formation. Madame, Monsieur, merci pour votre projet reçu le 8 mars. Avant son examen par notre conseil, pourriez-vous préciser le délai de préavis en cas d’indisponibilité de la salle et indiquer si le matériel est inclus dans les frais de location ? Nous vous serions reconnaissants de nous répondre avant le 20 mars et de transmettre, si nécessaire, une version actualisée. La signature dépendra de l’examen du conseil. Cordialement, Samira Benali.',de:'Betreff: Klärung der Fortbildungsvereinbarung. Sehr geehrte Damen und Herren, vielen Dank für Ihren Entwurf vom 8. März. Könnten Sie vor der Prüfung durch unseren Vorstand die Vorankündigungsfrist bei Nichtverfügbarkeit des Raums und die Frage klären, ob die Ausstattung in der Miete enthalten ist? Bitte senden Sie uns die Angaben und gegebenenfalls eine aktualisierte Fassung vor dem 20. März. Die Unterzeichnung hängt von der Prüfung des Vorstands ab. Mit freundlichen Grüßen, Samira Benali.',es:'Asunto: aclaraciones sobre el convenio de formación. Estimados señores: gracias por el borrador recibido el 8 de marzo. Antes de la revisión por nuestro consejo, ¿podrían precisar el plazo de preaviso si la sala no está disponible e indicar si el material está incluido en el alquiler? Les agradeceríamos una respuesta antes del 20 de marzo y, si fuera necesario, una versión actualizada. La firma dependerá de la revisión del consejo. Atentamente, Samira Benali.'}},

];
export const c1DeepeningModules:readonly TopicDeepening[]=[...initial,...c1FoundationExpansion,...c1SurvivalExpansion];
export function c1Deepening(section:C1Section,number:number):TopicDeepening|undefined{return c1DeepeningModules.find(item=>item.section===section&&item.number===number);}
